#!/usr/bin/env python3
"""Portable Research Swarm: copy this file into any project (Python 3.11+).

  python communication_hub.py init
  python communication_hub.py gui
  python communication_hub.py configure --apply
  python communication_hub.py --agent codex messages

Scales up to 64 active agent identities. Offline inboxes are durable.
No original project messages, credentials, absolute paths, or dependencies ship.
"""
import base64, hashlib, io, os, sys, tempfile, zipfile
from pathlib import Path

_payload = base64.b64decode('')
if hashlib.sha256(_payload).hexdigest() != '358100c3bb08af6af9545c9299e432feeee7f4d66e863b9b163adf6de4ebdbe5':
    raise SystemExit("Portable hub payload integrity check failed")
_project = Path(__file__).resolve().parent
_runtime = _project / ".communication-hub" / "runtime-358100c3bb08"
if not _runtime.resolve().is_relative_to(_project):
    raise SystemExit("Portable hub runtime cache must stay inside this project; external symlinks or junctions are not allowed")
with zipfile.ZipFile(io.BytesIO(_payload)) as _archive:
    for _entry in _archive.infolist():
        _target = (_runtime / _entry.filename).resolve()
        if not _target.is_relative_to(_runtime.resolve()):
            raise SystemExit("Invalid portable archive path")
        _content = _archive.read(_entry)
        if not _target.exists() or _target.read_bytes() != _content:
            _target.parent.mkdir(parents=True, exist_ok=True)
            _fd, _temporary = tempfile.mkstemp(dir=_target.parent, prefix=".hub-")
            try:
                with os.fdopen(_fd, "wb") as _stream:
                    _stream.write(_content)
                os.replace(_temporary, _target)
            finally:
                if os.path.exists(_temporary): os.unlink(_temporary)
sys.path.insert(0, str(_runtime))
from swarm.entrypoint import main
_arguments = sys.argv[1:]
if "--root" not in _arguments and not any(x.startswith("--root=") for x in _arguments):
    _arguments = ["--root", str(_project)] + _arguments
raise SystemExit(main(_arguments))
